// TestSessionClose tests closing a session
func TestSessionClose(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}

	sessionID := session.SessionID()

	// Close the session
	err = session.Close()
	if err != nil {
		t.Fatalf("Failed to close session: %v", err)
	}

	t.Logf("Session %d closed successfully", sessionID)
}

// TestTransactionStartAndCommit tests starting a transaction and committing
func TestTransactionStartAndCommit(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	// Start transaction
	txn, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatal(err)
	}

	// Verify transaction ID is generated by server
	if txn.TransactionID() == 0 {
		t.Error("Expected non-zero transaction ID from server")
	}

	t.Logf("Transaction started: %d", txn.TransactionID())

	// Verify session tracks the transaction
	if !session.HasTransaction() {
		t.Error("Session should have active transaction")
	}

	// Commit transaction
	err = txn.Commit()
	if err != nil {
		t.Fatalf("Failed to commit transaction: %v", err)
	}

	// Verify transaction is closed
	if !txn.IsClosed() {
		t.Error("Transaction should be closed after commit")
	}

	// Verify session no longer has transaction
	if session.HasTransaction() {
		t.Error("Session should not have active transaction after commit")
	}

	t.Log("Transaction committed successfully")
}

// TestTransactionStartAndRollback tests starting a transaction and rolling back
func TestTransactionStartAndRollback(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	// Start transaction
	txn, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatal(err)
	}

	t.Logf("Transaction started: %d", txn.TransactionID())

	// Rollback transaction
	err = txn.Rollback()
	if err != nil {
		t.Fatalf("Failed to rollback transaction: %v", err)
	}

	// Verify transaction is closed
	if !txn.IsClosed() {
		t.Error("Transaction should be closed after rollback")
	}

	// Verify session no longer has transaction
	if session.HasTransaction() {
		t.Error("Session should not have active transaction after rollback")
	}

	t.Log("Transaction rolled back successfully")
}

