// TestTransactionOnlyOnePerSession tests that only one transaction can be active per session
func TestTransactionOnlyOnePerSession(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	// Start first transaction
	txn1, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatal(err)
	}

	t.Logf("First transaction started: %d", txn1.TransactionID())

	// Try to start second transaction - should fail
	_, err = session.StartTransaction(nil)
	if err == nil {
		t.Fatal("Expected error when starting second transaction, but got none")
	}

	t.Logf("Expected error received: %v", err)

	// Commit first transaction
	err = txn1.Commit()
	if err != nil {
		t.Fatal(err)
	}

	// Now we can start a new transaction
	txn2, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatalf("Failed to start new transaction after committing first: %v", err)
	}
	defer txn2.Close()

	t.Logf("Second transaction started successfully: %d", txn2.TransactionID())
}

// TestTransactionAutoClose tests auto-rollback on Close()
func TestTransactionAutoClose(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	txn, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatal(err)
	}

	txnID := txn.TransactionID()
	t.Logf("Transaction started: %d", txnID)

	// Close without commit or rollback - should auto-rollback
	err = txn.Close()
	if err != nil {
		t.Fatalf("Failed to close transaction: %v", err)
	}

	// Verify transaction is closed
	if !txn.IsClosed() {
		t.Error("Transaction should be closed after Close()")
	}

	// Verify session no longer has transaction
	if session.HasTransaction() {
		t.Error("Session should not have active transaction after auto-rollback")
	}

	t.Log("Transaction auto-rolled back on Close()")
}

// TestTransactionClosedOperations tests operations on closed transaction
func TestTransactionClosedOperations(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	txn, err := session.StartTransaction(nil)
	if err != nil {
		t.Fatal(err)
	}

	// Commit the transaction
	err = txn.Commit()
	if err != nil {
		t.Fatal(err)
	}

	// Try to execute query on closed transaction
	_, err = txn.Gql("MATCH (n) RETURN n LIMIT 1", nil)
	if err == nil {
		t.Fatal("Expected error when executing query on closed transaction")
	}

	t.Logf("Expected error received: %v", err)

	// Try to commit again
	err = txn.Commit()
	if err == nil {
		t.Fatal("Expected error when committing closed transaction")
	}

	t.Logf("Expected error on double commit: %v", err)

	// Try to rollback
	err = txn.Rollback()
	if err == nil {
		t.Fatal("Expected error when rolling back closed transaction")
	}

	t.Logf("Expected error on rollback after commit: %v", err)
}

// TestTransactionWithConfig tests transaction with configuration
func TestTransactionWithConfig(t *testing.T) {
	session, err := client.Session(nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	txnConfig := &configuration.TransactionConfig{
		ReadOnly:           true,
		TransactionTimeout: 30,
	}

	txn, err := session.StartTransaction(txnConfig)
	if err != nil {
		t.Fatal(err)
	}
	defer txn.Close()

	t.Logf("Transaction with config started: %d", txn.TransactionID())

	// Execute read query
	resp, err := txn.Gql("MATCH (n) RETURN n LIMIT 1", nil)
	if err != nil {
		t.Fatal(err)
	}

	if !resp.IsSuccess() {
		t.Fatalf("Query failed: %s", resp.Status.Message)
	}

	t.Log("Read-only transaction executed successfully")
}

